create table if not exists public.hr_start_kit_lines (
  item_id     text    not null,
  kit         text    not null check (kit in ('account', 'hero', 'practice')),
  qty         bigint  not null check (qty > 0),
  set_id      text    check ((kit = 'practice') = (set_id is not null)),
  equip_slot  text    check ((kit = 'practice') = (equip_slot is not null)),
  worn        boolean not null default false check (kit = 'practice' or not worn),
  default_set boolean not null default false check (kit = 'practice' or not default_set),
  primary key (kit, item_id)
);
alter table public.hr_start_kit_lines enable row level security;
