-- ── Self-verification ────────────────────────────────────────────────────
do $$
declare v_bad text;
begin
  if (select count(*) from public.hr_start_kit_lines) <> 14 then
    raise exception 'hr_start_kit_lines holds % lines, the generator emitted 14', (select count(*) from public.hr_start_kit_lines);
  end if;
  select string_agg(l.item_id, ', ') into v_bad from public.hr_start_kit_lines l
   where not exists (select 1 from public.hr_items i where i.item_id = l.item_id)
      or (l.kit = 'practice' and not exists (select 1 from public.hr_item_slots s where s.item_id = l.item_id and s.equip_slot = l.equip_slot));
  if v_bad is not null then raise exception 'hr_start_kit_lines names an unknown item or an illegal slot: %', v_bad; end if;
  -- every set wears one weapon, no set wears two items in one slot, and exactly one set is the default
  select string_agg(x.set_id, ', ') into v_bad from (
    select set_id from public.hr_start_kit_lines where kit = 'practice' group by set_id
    having count(*) filter (where worn and equip_slot = 'weapon') <> 1
        or count(*) filter (where worn) <> count(distinct equip_slot) filter (where worn)) x;
  if v_bad is not null then raise exception 'hr_start_kit_lines: a set wears no weapon or two items in one slot: %', v_bad; end if;
  if (select count(distinct set_id) from public.hr_start_kit_lines where default_set) <> 1 then
    raise exception 'hr_start_kit_lines: not exactly one default set';
  end if;
  if has_table_privilege('anon', 'public.hr_start_kit_lines', 'select') or has_table_privilege('authenticated', 'public.hr_start_kit_lines', 'select,insert,update,delete') then
    raise exception 'hr_start_kit_lines is readable or writable by a client role';
  end if;
  raise notice 'hr_start_kit_lines OK — 14 lines, digest b863ee889cfcde207da0b4f4621178695d8b9c5477a06dc1591e793947d273e9';
end $$;
